const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
  lines.push(line);
  if (lines.length === 4) {
    const n = parseInt(lines[0]);
    let s = lines[1].split(' ');
    let min1 = parseInt(s[0]), max1 = parseInt(s[1]);
    s = lines[2].split(' ');
    let min2 = parseInt(s[0]), max2 = parseInt(s[1]);
    s = lines[3].split(' ');
    let min3 = parseInt(s[0]), max3 = parseInt(s[1]);
    if (n - min3 - min2 <= max1) {
      console.log((n - min3 - min2) + ' ' + min2 + ' ' + min3);
    } else if (n - max1 - min3 <= max2) {
      console.log(max1 + ' ' + (n - max1 - min3) + ' ' + min3);
    } else {
      console.log(max1 + ' ' + max2 + ' ' + (n - max1 - max2));
    }
    rl.close();
  }
});
